import { describe, it } from 'node:test';
import { strict as assert } from 'node:assert';
import { createInvoice, lineTotal, lineDiscount, invoiceTotals, addLine, removeLine, issueInvoice } from '../src/invoices.js';
import { nextInvoiceNumber } from '../src/numbering.js';
import { listCustomers } from '../src/customers.js';
import { listProducts } from '../src/catalogue.js';

describe('createInvoice', () => {
  it('creates a valid invoice with one line', () => {
    const products = listProducts();
    const customers = listCustomers();
    const sku = products[0].sku;
    const customerId = customers[0].id;

    const result = createInvoice({
      customerId,
      issueDate: '2025-01-15',
      lines: [{ sku, qty: 2 }],
    });

    assert.equal(result.ok, true);
    assert.equal(result.value.customerId, customerId);
    assert.equal(result.value.issueDate, '2025-01-15');
    assert.equal(result.value.status, 'draft');
    assert.equal(result.value.lines.length, 1);
    assert.equal(result.value.lines[0].sku, sku);
    assert.equal(result.value.lines[0].name, products[0].name);
    assert.equal(result.value.lines[0].qty, 2);
    assert.equal(result.value.lines[0].unitPrice, products[0].unitPrice);
    assert.equal(result.value.lines[0].vatRate, products[0].vatRate);
  });

  it('creates a valid invoice with multiple lines', () => {
    const products = listProducts();
    const customers = listCustomers();
    const customer = customers[0];
    const product1 = products[0];
    const product2 = products[1];

    const result = createInvoice({
      customerId: customer.id,
      issueDate: '2025-02-20',
      lines: [
        { sku: product1.sku, qty: 3 },
        { sku: product2.sku, qty: 5 },
      ],
    });

    assert.equal(result.ok, true);
    assert.equal(result.value.lines.length, 2);
    assert.equal(result.value.lines[0].sku, product1.sku);
    assert.equal(result.value.lines[0].qty, 3);
    assert.equal(result.value.lines[1].sku, product2.sku);
    assert.equal(result.value.lines[1].qty, 5);
  });

  it('does not mutate the input lines array', () => {
    const products = listProducts();
    const customers = listCustomers();
    const lines = [{ sku: products[0].sku, qty: 1 }];
    const linesCopy = JSON.parse(JSON.stringify(lines));

    createInvoice({
      customerId: customers[0].id,
      issueDate: '2025-01-15',
      lines,
    });

    assert.deepEqual(lines, linesCopy);
  });

  describe('customer validation', () => {
    it('returns CUSTOMER_NOT_FOUND for unknown customer', () => {
      const products = listProducts();
      const result = createInvoice({
        customerId: 'unknown-customer-id',
        issueDate: '2025-01-15',
        lines: [{ sku: products[0].sku, qty: 1 }],
      });

      assert.equal(result.ok, false);
      assert.equal(result.error, 'CUSTOMER_NOT_FOUND');
    });
  });

  describe('date validation', () => {
    it('returns DATE_INVALID for wrong format (DD/MM/YYYY)', () => {
      const products = listProducts();
      const customers = listCustomers();
      const result = createInvoice({
        customerId: customers[0].id,
        issueDate: '15/01/2025',
        lines: [{ sku: products[0].sku, qty: 1 }],
      });

      assert.equal(result.ok, false);
      assert.equal(result.error, 'DATE_INVALID');
    });

    it('returns DATE_INVALID for wrong format (no hyphens)', () => {
      const products = listProducts();
      const customers = listCustomers();
      const result = createInvoice({
        customerId: customers[0].id,
        issueDate: '20250115',
        lines: [{ sku: products[0].sku, qty: 1 }],
      });

      assert.equal(result.ok, false);
      assert.equal(result.error, 'DATE_INVALID');
    });

    it('returns DATE_INVALID for impossible date (Feb 30)', () => {
      const products = listProducts();
      const customers = listCustomers();
      const result = createInvoice({
        customerId: customers[0].id,
        issueDate: '2025-02-30',
        lines: [{ sku: products[0].sku, qty: 1 }],
      });

      assert.equal(result.ok, false);
      assert.equal(result.error, 'DATE_INVALID');
    });

    it('returns DATE_INVALID for impossible date (month 13)', () => {
      const products = listProducts();
      const customers = listCustomers();
      const result = createInvoice({
        customerId: customers[0].id,
        issueDate: '2025-13-01',
        lines: [{ sku: products[0].sku, qty: 1 }],
      });

      assert.equal(result.ok, false);
      assert.equal(result.error, 'DATE_INVALID');
    });

    it('accepts valid leap year date', () => {
      const products = listProducts();
      const customers = listCustomers();
      const result = createInvoice({
        customerId: customers[0].id,
        issueDate: '2024-02-29',
        lines: [{ sku: products[0].sku, qty: 1 }],
      });

      assert.equal(result.ok, true);
    });

    it('returns DATE_INVALID for non-leap year Feb 29', () => {
      const products = listProducts();
      const customers = listCustomers();
      const result = createInvoice({
        customerId: customers[0].id,
        issueDate: '2025-02-29',
        lines: [{ sku: products[0].sku, qty: 1 }],
      });

      assert.equal(result.ok, false);
      assert.equal(result.error, 'DATE_INVALID');
    });
  });

  describe('lines validation', () => {
    it('returns NO_LINES for empty lines array', () => {
      const customers = listCustomers();
      const result = createInvoice({
        customerId: customers[0].id,
        issueDate: '2025-01-15',
        lines: [],
      });

      assert.equal(result.ok, false);
      assert.equal(result.error, 'NO_LINES');
    });

    it('returns NO_LINES when lines is not an array', () => {
      const customers = listCustomers();
      const result = createInvoice({
        customerId: customers[0].id,
        issueDate: '2025-01-15',
        lines: null,
      });

      assert.equal(result.ok, false);
      assert.equal(result.error, 'NO_LINES');
    });
  });

  describe('quantity validation', () => {
    it('returns QTY_INVALID for non-integer quantity', () => {
      const products = listProducts();
      const customers = listCustomers();
      const result = createInvoice({
        customerId: customers[0].id,
        issueDate: '2025-01-15',
        lines: [{ sku: products[0].sku, qty: 1.5 }],
      });

      assert.equal(result.ok, false);
      assert.equal(result.error, 'QTY_INVALID');
    });

    it('returns QTY_INVALID for zero quantity', () => {
      const products = listProducts();
      const customers = listCustomers();
      const result = createInvoice({
        customerId: customers[0].id,
        issueDate: '2025-01-15',
        lines: [{ sku: products[0].sku, qty: 0 }],
      });

      assert.equal(result.ok, false);
      assert.equal(result.error, 'QTY_INVALID');
    });

    it('returns QTY_INVALID for negative quantity', () => {
      const products = listProducts();
      const customers = listCustomers();
      const result = createInvoice({
        customerId: customers[0].id,
        issueDate: '2025-01-15',
        lines: [{ sku: products[0].sku, qty: -5 }],
      });

      assert.equal(result.ok, false);
      assert.equal(result.error, 'QTY_INVALID');
    });

    it('returns QTY_INVALID for string quantity', () => {
      const products = listProducts();
      const customers = listCustomers();
      const result = createInvoice({
        customerId: customers[0].id,
        issueDate: '2025-01-15',
        lines: [{ sku: products[0].sku, qty: '5' }],
      });

      assert.equal(result.ok, false);
      assert.equal(result.error, 'QTY_INVALID');
    });

    it('accepts large positive integer quantities', () => {
      const products = listProducts();
      const customers = listCustomers();
      const result = createInvoice({
        customerId: customers[0].id,
        issueDate: '2025-01-15',
        lines: [{ sku: products[0].sku, qty: 999999 }],
      });

      assert.equal(result.ok, true);
      assert.equal(result.value.lines[0].qty, 999999);
    });
  });

  describe('discount validation', () => {
    it('accepts discountPercent of 0', () => {
      const products = listProducts();
      const customers = listCustomers();
      const result = createInvoice({
        customerId: customers[0].id,
        issueDate: '2025-01-15',
        lines: [{ sku: products[0].sku, qty: 1, discountPercent: 0 }],
      });

      assert.equal(result.ok, true);
      assert.equal(result.value.lines[0].discountPercent, 0);
    });

    it('accepts discountPercent of 100', () => {
      const products = listProducts();
      const customers = listCustomers();
      const result = createInvoice({
        customerId: customers[0].id,
        issueDate: '2025-01-15',
        lines: [{ sku: products[0].sku, qty: 1, discountPercent: 100 }],
      });

      assert.equal(result.ok, true);
      assert.equal(result.value.lines[0].discountPercent, 100);
    });

    it('accepts decimal discountPercent like 12.5', () => {
      const products = listProducts();
      const customers = listCustomers();
      const result = createInvoice({
        customerId: customers[0].id,
        issueDate: '2025-01-15',
        lines: [{ sku: products[0].sku, qty: 1, discountPercent: 12.5 }],
      });

      assert.equal(result.ok, true);
      assert.equal(result.value.lines[0].discountPercent, 12.5);
    });

    it('defaults discountPercent to 0 when not provided', () => {
      const products = listProducts();
      const customers = listCustomers();
      const result = createInvoice({
        customerId: customers[0].id,
        issueDate: '2025-01-15',
        lines: [{ sku: products[0].sku, qty: 1 }],
      });

      assert.equal(result.ok, true);
      assert.equal(result.value.lines[0].discountPercent, 0);
    });

    it('returns DISCOUNT_INVALID for negative discountPercent', () => {
      const products = listProducts();
      const customers = listCustomers();
      const result = createInvoice({
        customerId: customers[0].id,
        issueDate: '2025-01-15',
        lines: [{ sku: products[0].sku, qty: 1, discountPercent: -5 }],
      });

      assert.equal(result.ok, false);
      assert.equal(result.error, 'DISCOUNT_INVALID');
    });

    it('returns DISCOUNT_INVALID for discountPercent > 100', () => {
      const products = listProducts();
      const customers = listCustomers();
      const result = createInvoice({
        customerId: customers[0].id,
        issueDate: '2025-01-15',
        lines: [{ sku: products[0].sku, qty: 1, discountPercent: 105 }],
      });

      assert.equal(result.ok, false);
      assert.equal(result.error, 'DISCOUNT_INVALID');
    });

    it('returns DISCOUNT_INVALID for non-number discountPercent', () => {
      const products = listProducts();
      const customers = listCustomers();
      const result = createInvoice({
        customerId: customers[0].id,
        issueDate: '2025-01-15',
        lines: [{ sku: products[0].sku, qty: 1, discountPercent: '50' }],
      });

      assert.equal(result.ok, false);
      assert.equal(result.error, 'DISCOUNT_INVALID');
    });
  });

  describe('SKU validation', () => {
    it('returns UNKNOWN_SKU for unknown product', () => {
      const customers = listCustomers();
      const result = createInvoice({
        customerId: customers[0].id,
        issueDate: '2025-01-15',
        lines: [{ sku: 'UNKNOWN-SKU-12345', qty: 1 }],
      });

      assert.equal(result.ok, false);
      assert.equal(result.error, 'UNKNOWN_SKU');
    });

    it('returns UNKNOWN_SKU when first line has unknown SKU', () => {
      const products = listProducts();
      const customers = listCustomers();
      const result = createInvoice({
        customerId: customers[0].id,
        issueDate: '2025-01-15',
        lines: [
          { sku: 'UNKNOWN-SKU', qty: 1 },
          { sku: products[0].sku, qty: 1 },
        ],
      });

      assert.equal(result.ok, false);
      assert.equal(result.error, 'UNKNOWN_SKU');
    });

    it('returns UNKNOWN_SKU when second line has unknown SKU', () => {
      const products = listProducts();
      const customers = listCustomers();
      const result = createInvoice({
        customerId: customers[0].id,
        issueDate: '2025-01-15',
        lines: [
          { sku: products[0].sku, qty: 1 },
          { sku: 'UNKNOWN-SKU', qty: 1 },
        ],
      });

      assert.equal(result.ok, false);
      assert.equal(result.error, 'UNKNOWN_SKU');
    });
  });

  describe('error priority', () => {
    it('validates customer before date', () => {
      const products = listProducts();
      const result = createInvoice({
        customerId: 'unknown',
        issueDate: 'invalid-date',
        lines: [{ sku: products[0].sku, qty: 1 }],
      });

      assert.equal(result.error, 'CUSTOMER_NOT_FOUND');
    });

    it('validates date before lines', () => {
      const products = listProducts();
      const customers = listCustomers();
      const result = createInvoice({
        customerId: customers[0].id,
        issueDate: 'invalid-date',
        lines: [],
      });

      assert.equal(result.error, 'DATE_INVALID');
    });

    it('validates lines array before line contents', () => {
      const customers = listCustomers();
      const result = createInvoice({
        customerId: customers[0].id,
        issueDate: '2025-01-15',
        lines: [],
      });

      assert.equal(result.error, 'NO_LINES');
    });
  });
});

describe('lineTotal', () => {
  it('calculates qty times unitPrice', () => {
    const total = lineTotal({ qty: 3, unitPrice: 500 });
    assert.equal(total, 1500);
  });

  it('returns a whole number of cents', () => {
    const total = lineTotal({ qty: 3, unitPrice: 500 });
    assert.equal(Number.isInteger(total), true);
  });

  it('handles qty of 1', () => {
    const total = lineTotal({ qty: 1, unitPrice: 999 });
    assert.equal(total, 999);
  });

  it('handles large quantities', () => {
    const total = lineTotal({ qty: 1000000, unitPrice: 50 });
    assert.equal(total, 50000000);
  });

  it('rounds fractional cents to nearest even (banker\'s rounding)', () => {
    const total1 = lineTotal({ qty: 3, unitPrice: 100.5 });
    assert.equal(total1, 302);

    const total2 = lineTotal({ qty: 3, unitPrice: 100.4 });
    assert.equal(total2, 301);
  });

  it('handles products with low unit prices', () => {
    const total = lineTotal({ qty: 3, unitPrice: 1 });
    assert.equal(total, 3);
  });

  it('does not mutate the input', () => {
    const line = { qty: 5, unitPrice: 200 };
    const lineCopy = JSON.parse(JSON.stringify(line));
    lineTotal(line);
    assert.deepEqual(line, lineCopy);
  });
});

describe('lineDiscount', () => {
  it('calculates discount as lineTotal * (discountPercent / 100)', () => {
    const discount = lineDiscount({ qty: 10, unitPrice: 100, discountPercent: 10 });
    assert.equal(discount, 100);
  });

  it('returns 0 for 0% discount', () => {
    const discount = lineDiscount({ qty: 10, unitPrice: 100, discountPercent: 0 });
    assert.equal(discount, 0);
  });

  it('returns full line total for 100% discount', () => {
    const discount = lineDiscount({ qty: 10, unitPrice: 100, discountPercent: 100 });
    assert.equal(discount, 1000);
  });

  it('handles decimal discounts like 12.5%', () => {
    const discount = lineDiscount({ qty: 8, unitPrice: 100, discountPercent: 12.5 });
    assert.equal(discount, 100);
  });

  it('defaults discountPercent to 0 when not provided', () => {
    const discount = lineDiscount({ qty: 10, unitPrice: 100 });
    assert.equal(discount, 0);
  });

  it('rounds discount to nearest cent', () => {
    const discount = lineDiscount({ qty: 3, unitPrice: 100.5, discountPercent: 33.33 });
    assert.equal(Number.isInteger(discount), true);
  });

  it('clamps negative discount at 0', () => {
    const discount = lineDiscount({ qty: 1, unitPrice: -100, discountPercent: 10 });
    assert.equal(discount, 0);
  });

  it('does not mutate the input', () => {
    const line = { qty: 5, unitPrice: 200, discountPercent: 10 };
    const lineCopy = JSON.parse(JSON.stringify(line));
    lineDiscount(line);
    assert.deepEqual(line, lineCopy);
  });
});

describe('invoiceTotals', () => {
  it('calculates subtotal for single line', () => {
    const invoice = {
      lines: [{ qty: 2, unitPrice: 500 }],
    };
    const totals = invoiceTotals(invoice);
    assert.equal(totals.subtotal, 1000);
  });

  it('includes discount in totals', () => {
    const invoice = {
      lines: [{ qty: 2, unitPrice: 500, discountPercent: 10 }],
    };
    const totals = invoiceTotals(invoice);
    assert.equal(totals.discount, 100);
  });

  it('calculates total as subtotal minus discount', () => {
    const invoice = {
      lines: [{ qty: 2, unitPrice: 500, discountPercent: 10 }],
    };
    const totals = invoiceTotals(invoice);
    assert.equal(totals.subtotal, 1000);
    assert.equal(totals.discount, 100);
    assert.equal(totals.total, 900);
  });

  it('total equals subtotal when no discount', () => {
    const invoice = {
      lines: [{ qty: 2, unitPrice: 500 }],
    };
    const totals = invoiceTotals(invoice);
    assert.equal(totals.total, totals.subtotal);
  });

  it('calculates subtotal for multiple lines', () => {
    const invoice = {
      lines: [
        { qty: 2, unitPrice: 500 },
        { qty: 3, unitPrice: 200 },
      ],
    };
    const totals = invoiceTotals(invoice);
    assert.equal(totals.subtotal, 1600);
  });

  it('sums discounts across multiple lines', () => {
    const invoice = {
      lines: [
        { qty: 2, unitPrice: 500, discountPercent: 10 },
        { qty: 3, unitPrice: 200, discountPercent: 5 },
      ],
    };
    const totals = invoiceTotals(invoice);
    assert.equal(totals.subtotal, 1600);
    assert.equal(totals.discount, 130);
    assert.equal(totals.total, 1470);
  });

  it('clamps total at 0 when discount exceeds subtotal', () => {
    const invoice = {
      lines: [{ qty: 2, unitPrice: 500, discountPercent: 110 }],
    };
    const totals = invoiceTotals(invoice);
    assert.equal(totals.subtotal, 1000);
    assert.equal(totals.discount, 1000);
    assert.equal(totals.total, 0);
  });

  it('handles empty lines', () => {
    const invoice = { lines: [] };
    const totals = invoiceTotals(invoice);
    assert.equal(totals.subtotal, 0);
    assert.equal(totals.discount, 0);
    assert.equal(totals.total, 0);
  });

  it('returns whole number of cents', () => {
    const invoice = {
      lines: [
        { qty: 3, unitPrice: 100 },
        { qty: 2, unitPrice: 250 },
      ],
    };
    const totals = invoiceTotals(invoice);
    assert.equal(Number.isInteger(totals.subtotal), true);
    assert.equal(Number.isInteger(totals.total), true);
  });

  it('rounds each line individually then sums', () => {
    const invoice = {
      lines: [
        { qty: 3, unitPrice: 100.5 },
        { qty: 2, unitPrice: 150.5 },
      ],
    };
    const totals = invoiceTotals(invoice);
    const line1Total = lineTotal(invoice.lines[0]);
    const line2Total = lineTotal(invoice.lines[1]);
    assert.equal(totals.subtotal, line1Total + line2Total);
  });

  it('works with real invoice from createInvoice', () => {
    const products = listProducts();
    const customers = listCustomers();
    const invoiceResult = createInvoice({
      customerId: customers[0].id,
      issueDate: '2025-01-15',
      lines: [
        { sku: products[0].sku, qty: 2 },
        { sku: products[1].sku, qty: 3 },
      ],
    });

    assert.equal(invoiceResult.ok, true);
    const totals = invoiceTotals(invoiceResult.value);
    assert.equal(
      totals.subtotal,
      lineTotal(invoiceResult.value.lines[0]) + lineTotal(invoiceResult.value.lines[1])
    );
    assert.equal(totals.total, totals.subtotal);
  });

  it('works with discounts from createInvoice', () => {
    const products = listProducts();
    const customers = listCustomers();
    const invoiceResult = createInvoice({
      customerId: customers[0].id,
      issueDate: '2025-01-15',
      lines: [
        { sku: products[0].sku, qty: 2, discountPercent: 10 },
        { sku: products[1].sku, qty: 3, discountPercent: 5 },
      ],
    });

    assert.equal(invoiceResult.ok, true);
    const totals = invoiceTotals(invoiceResult.value);
    assert.equal(
      totals.subtotal,
      lineTotal(invoiceResult.value.lines[0]) + lineTotal(invoiceResult.value.lines[1])
    );
    const expectedDiscount = lineDiscount(invoiceResult.value.lines[0]) + lineDiscount(invoiceResult.value.lines[1]);
    assert.equal(totals.discount, expectedDiscount);
    assert.equal(totals.total, totals.subtotal - totals.discount);
  });

  it('returns 0 for discount field', () => {
    const invoice = {
      lines: [{ qty: 2, unitPrice: 500 }],
    };
    const totals = invoiceTotals(invoice);
    assert.equal(totals.discount, 0);
  });

  it('does not mutate the input', () => {
    const invoice = {
      lines: [{ qty: 2, unitPrice: 500 }],
    };
    const invoiceCopy = JSON.parse(JSON.stringify(invoice));
    invoiceTotals(invoice);
    assert.deepEqual(invoice, invoiceCopy);
  });

  it('returns new object on each call', () => {
    const invoice = {
      lines: [{ qty: 2, unitPrice: 500 }],
    };
    const totals1 = invoiceTotals(invoice);
    const totals2 = invoiceTotals(invoice);
    assert.notEqual(totals1, totals2);
    assert.deepEqual(totals1, totals2);
  });

  it('handles large invoices', () => {
    const invoice = {
      lines: Array.from({ length: 100 }, (_, i) => ({
        qty: i + 1,
        unitPrice: 100,
      })),
    };
    const totals = invoiceTotals(invoice);
    assert.equal(Number.isInteger(totals.subtotal), true);
    const expected = Array.from({ length: 100 }, (_, i) => (i + 1) * 100).reduce((a, b) => a + b);
    assert.equal(totals.subtotal, expected);
  });
});

