describe('lineTotal', () => {
  it('calculates qty times unitPrice', () => {
    const total = lineTotal({ qty: 3, unitPrice: 500 });
    assert.equal(total, 1500);
  });

  it('returns a whole number of cents', () => {
    const total = lineTotal({ qty: 3, unitPrice: 500 });
    assert.equal(Number.isInteger(total), true);
  });

  it('handles qty of 1', () => {
    const total = lineTotal({ qty: 1, unitPrice: 999 });
    assert.equal(total, 999);
  });

  it('handles large quantities', () => {
    const total = lineTotal({ qty: 1000000, unitPrice: 50 });
    assert.equal(total, 50000000);
  });

  it('rounds fractional cents to nearest even (banker\'s rounding)', () => {
    const total1 = lineTotal({ qty: 3, unitPrice: 100.5 });
    assert.equal(total1, 302);

    const total2 = lineTotal({ qty: 3, unitPrice: 100.4 });
    assert.equal(total2, 301);
  });

  it('handles products with low unit prices', () => {
    const total = lineTotal({ qty: 3, unitPrice: 1 });
    assert.equal(total, 3);
  });

  it('does not mutate the input', () => {
    const line = { qty: 5, unitPrice: 200 };
    const lineCopy = JSON.parse(JSON.stringify(line));
    lineTotal(line);
    assert.deepEqual(line, lineCopy);
  });
});

describe('lineDiscount', () => {
  it('calculates discount as lineTotal * (discountPercent / 100)', () => {
    const discount = lineDiscount({ qty: 10, unitPrice: 100, discountPercent: 10 });
    assert.equal(discount, 100);
  });

  it('returns 0 for 0% discount', () => {
    const discount = lineDiscount({ qty: 10, unitPrice: 100, discountPercent: 0 });
    assert.equal(discount, 0);
  });

  it('returns full line total for 100% discount', () => {
    const discount = lineDiscount({ qty: 10, unitPrice: 100, discountPercent: 100 });
    assert.equal(discount, 1000);
  });

  it('handles decimal discounts like 12.5%', () => {
    const discount = lineDiscount({ qty: 8, unitPrice: 100, discountPercent: 12.5 });
    assert.equal(discount, 100);
  });

  it('defaults discountPercent to 0 when not provided', () => {
    const discount = lineDiscount({ qty: 10, unitPrice: 100 });
    assert.equal(discount, 0);
  });

  it('rounds discount to nearest cent', () => {
    const discount = lineDiscount({ qty: 3, unitPrice: 100.5, discountPercent: 33.33 });
    assert.equal(Number.isInteger(discount), true);
  });

  it('clamps negative discount at 0', () => {
    const discount = lineDiscount({ qty: 1, unitPrice: -100, discountPercent: 10 });
    assert.equal(discount, 0);
  });

  it('does not mutate the input', () => {
    const line = { qty: 5, unitPrice: 200, discountPercent: 10 };
    const lineCopy = JSON.parse(JSON.stringify(line));
    lineDiscount(line);
    assert.deepEqual(line, lineCopy);
  });
});

describe('invoiceTotals', () => {
  it('calculates subtotal for single line', () => {
    const invoice = {
      lines: [{ qty: 2, unitPrice: 500 }],
    };
    const totals = invoiceTotals(invoice);
    assert.equal(totals.subtotal, 1000);
  });

  it('includes discount in totals', () => {
    const invoice = {
      lines: [{ qty: 2, unitPrice: 500, discountPercent: 10 }],
    };
    const totals = invoiceTotals(invoice);
    assert.equal(totals.discount, 100);
  });

  it('calculates total as subtotal minus discount', () => {
    const invoice = {
      lines: [{ qty: 2, unitPrice: 500, discountPercent: 10 }],
    };
    const totals = invoiceTotals(invoice);
    assert.equal(totals.subtotal, 1000);
    assert.equal(totals.discount, 100);
    assert.equal(totals.total, 900);
  });

  it('total equals subtotal when no discount', () => {
    const invoice = {
      lines: [{ qty: 2, unitPrice: 500 }],
    };
    const totals = invoiceTotals(invoice);
    assert.equal(totals.total, totals.subtotal);
  });

  it('calculates subtotal for multiple lines', () => {
    const invoice = {
      lines: [
        { qty: 2, unitPrice: 500 },
        { qty: 3, unitPrice: 200 },
      ],
    };
    const totals = invoiceTotals(invoice);
    assert.equal(totals.subtotal, 1600);
  });

  it('sums discounts across multiple lines', () => {
    const invoice = {
      lines: [
        { qty: 2, unitPrice: 500, discountPercent: 10 },
        { qty: 3, unitPrice: 200, discountPercent: 5 },
      ],
    };
    const totals = invoiceTotals(invoice);
    assert.equal(totals.subtotal, 1600);
    assert.equal(totals.discount, 130);
    assert.equal(totals.total, 1470);
  });

  it('clamps total at 0 when discount exceeds subtotal', () => {
    const invoice = {
      lines: [{ qty: 2, unitPrice: 500, discountPercent: 110 }],
    };
    const totals = invoiceTotals(invoice);
    assert.equal(totals.subtotal, 1000);
    assert.equal(totals.discount, 1000);
    assert.equal(totals.total, 0);
  });

  it('handles empty lines', () => {
    const invoice = { lines: [] };
    const totals = invoiceTotals(invoice);
    assert.equal(totals.subtotal, 0);
    assert.equal(totals.discount, 0);
    assert.equal(totals.total, 0);
  });

  it('returns whole number of cents', () => {
    const invoice = {
      lines: [
        { qty: 3, unitPrice: 100 },
        { qty: 2, unitPrice: 250 },
      ],
    };
    const totals = invoiceTotals(invoice);
    assert.equal(Number.isInteger(totals.subtotal), true);
    assert.equal(Number.isInteger(totals.total), true);
  });

  it('rounds each line individually then sums', () => {
    const invoice = {
      lines: [
        { qty: 3, unitPrice: 100.5 },
        { qty: 2, unitPrice: 150.5 },
      ],
    };
    const totals = invoiceTotals(invoice);
    const line1Total = lineTotal(invoice.lines[0]);
    const line2Total = lineTotal(invoice.lines[1]);
    assert.equal(totals.subtotal, line1Total + line2Total);
  });

  it('works with real invoice from createInvoice', () => {
    const products = listProducts();
    const customers = listCustomers();
    const invoiceResult = createInvoice({
      customerId: customers[0].id,
      issueDate: '2025-01-15',
      lines: [
        { sku: products[0].sku, qty: 2 },
        { sku: products[1].sku, qty: 3 },
      ],
    });

    assert.equal(invoiceResult.ok, true);
    const totals = invoiceTotals(invoiceResult.value);
    assert.equal(
      totals.subtotal,
      lineTotal(invoiceResult.value.lines[0]) + lineTotal(invoiceResult.value.lines[1])
    );
    assert.equal(totals.total, totals.subtotal);
  });

  it('works with discounts from createInvoice', () => {
    const products = listProducts();
    const customers = listCustomers();
    const invoiceResult = createInvoice({
      customerId: customers[0].id,
      issueDate: '2025-01-15',
      lines: [
        { sku: products[0].sku, qty: 2, discountPercent: 10 },
        { sku: products[1].sku, qty: 3, discountPercent: 5 },
      ],
    });

    assert.equal(invoiceResult.ok, true);
    const totals = invoiceTotals(invoiceResult.value);
    assert.equal(
      totals.subtotal,
      lineTotal(invoiceResult.value.lines[0]) + lineTotal(invoiceResult.value.lines[1])
    );
    const expectedDiscount = lineDiscount(invoiceResult.value.lines[0]) + lineDiscount(invoiceResult.value.lines[1]);
    assert.equal(totals.discount, expectedDiscount);
    assert.equal(totals.total, totals.subtotal - totals.discount);
  });

  it('returns 0 for discount field', () => {
    const invoice = {
      lines: [{ qty: 2, unitPrice: 500 }],
    };
    const totals = invoiceTotals(invoice);
    assert.equal(totals.discount, 0);
  });

  it('does not mutate the input', () => {
    const invoice = {
      lines: [{ qty: 2, unitPrice: 500 }],
    };
    const invoiceCopy = JSON.parse(JSON.stringify(invoice));
    invoiceTotals(invoice);
    assert.deepEqual(invoice, invoiceCopy);
  });

  it('returns new object on each call', () => {
    const invoice = {
      lines: [{ qty: 2, unitPrice: 500 }],
    };
    const totals1 = invoiceTotals(invoice);
    const totals2 = invoiceTotals(invoice);
    assert.notEqual(totals1, totals2);
    assert.deepEqual(totals1, totals2);
  });

  it('handles large invoices', () => {
    const invoice = {
      lines: Array.from({ length: 100 }, (_, i) => ({
        qty: i + 1,
        unitPrice: 100,
      })),
    };
    const totals = invoiceTotals(invoice);
    assert.equal(Number.isInteger(totals.subtotal), true);
    const expected = Array.from({ length: 100 }, (_, i) => (i + 1) * 100).reduce((a, b) => a + b);
    assert.equal(totals.subtotal, expected);
  });
});

describe('addLine', () => {
  it('adds a new line to a draft invoice', () => {
    const products = listProducts();
    const customers = listCustomers();
    const invoiceResult = createInvoice({
      customerId: customers[0].id,
      issueDate: '2025-01-15',
      lines: [{ sku: products[0].sku, qty: 2 }],
    });

    const newProduct = products[1];
    const result = addLine(invoiceResult.value, { sku: newProduct.sku, qty: 3 });

    assert.equal(result.ok, true);
    assert.equal(result.value.lines.length, 2);
    assert.equal(result.value.lines[1].sku, newProduct.sku);
    assert.equal(result.value.lines[1].qty, 3);
    assert.equal(result.value.lines[1].name, newProduct.name);
  });

  it('increases qty if SKU already exists on invoice', () => {
    const products = listProducts();
    const customers = listCustomers();
    const sku = products[0].sku;
    const invoiceResult = createInvoice({
      customerId: customers[0].id,
      issueDate: '2025-01-15',
      lines: [{ sku, qty: 2 }],
    });

    const result = addLine(invoiceResult.value, { sku, qty: 3 });

    assert.equal(result.ok, true);
    assert.equal(result.value.lines.length, 1);
    assert.equal(result.value.lines[0].qty, 5);
  });

  it('does not mutate the original invoice', () => {
    const products = listProducts();
    const customers = listCustomers();
    const invoiceResult = createInvoice({
      customerId: customers[0].id,
      issueDate: '2025-01-15',
      lines: [{ sku: products[0].sku, qty: 2 }],
    });

    const invoice = invoiceResult.value;
    const invoiceCopy = JSON.parse(JSON.stringify(invoice));

    addLine(invoice, { sku: products[1].sku, qty: 1 });

    assert.deepEqual(invoice, invoiceCopy);
  });

  it('returns NOT_DRAFT for non-draft invoice', () => {
    const products = listProducts();
    const customers = listCustomers();
    const invoiceResult = createInvoice({
      customerId: customers[0].id,
      issueDate: '2025-01-15',
      lines: [{ sku: products[0].sku, qty: 2 }],
    });

    const invoice = invoiceResult.value;
    invoice.status = 'sent';

    const result = addLine(invoice, { sku: products[1].sku, qty: 1 });

    assert.equal(result.ok, false);
    assert.equal(result.error, 'NOT_DRAFT');
  });

  it('returns QTY_INVALID for non-integer quantity', () => {
    const products = listProducts();
    const customers = listCustomers();
    const invoiceResult = createInvoice({
      customerId: customers[0].id,
      issueDate: '2025-01-15',
      lines: [{ sku: products[0].sku, qty: 2 }],
    });

    const result = addLine(invoiceResult.value, { sku: products[1].sku, qty: 1.5 });

    assert.equal(result.ok, false);
    assert.equal(result.error, 'QTY_INVALID');
  });

  it('returns QTY_INVALID for zero quantity', () => {
    const products = listProducts();
    const customers = listCustomers();
    const invoiceResult = createInvoice({
      customerId: customers[0].id,
      issueDate: '2025-01-15',
      lines: [{ sku: products[0].sku, qty: 2 }],
    });

    const result = addLine(invoiceResult.value, { sku: products[1].sku, qty: 0 });

    assert.equal(result.ok, false);
    assert.equal(result.error, 'QTY_INVALID');
  });

  it('returns QTY_INVALID for negative quantity', () => {
    const products = listProducts();
    const customers = listCustomers();
    const invoiceResult = createInvoice({
      customerId: customers[0].id,
      issueDate: '2025-01-15',
      lines: [{ sku: products[0].sku, qty: 2 }],
    });

    const result = addLine(invoiceResult.value, { sku: products[1].sku, qty: -5 });

    assert.equal(result.ok, false);
    assert.equal(result.error, 'QTY_INVALID');
  });

  it('returns UNKNOWN_SKU for unknown product', () => {
    const products = listProducts();
    const customers = listCustomers();
    const invoiceResult = createInvoice({
      customerId: customers[0].id,
      issueDate: '2025-01-15',
      lines: [{ sku: products[0].sku, qty: 2 }],
    });

    const result = addLine(invoiceResult.value, { sku: 'UNKNOWN-SKU', qty: 1 });

    assert.equal(result.ok, false);
    assert.equal(result.error, 'UNKNOWN_SKU');
  });

  it('accepts discountPercent when adding a line', () => {
    const products = listProducts();
    const customers = listCustomers();
    const invoiceResult = createInvoice({
      customerId: customers[0].id,
      issueDate: '2025-01-15',
      lines: [{ sku: products[0].sku, qty: 2 }],
    });

    const result = addLine(invoiceResult.value, { sku: products[1].sku, qty: 3, discountPercent: 15 });

    assert.equal(result.ok, true);
    assert.equal(result.value.lines[1].discountPercent, 15);
  });

  it('defaults discountPercent to 0 when adding a line without it', () => {
    const products = listProducts();
    const customers = listCustomers();
    const invoiceResult = createInvoice({
      customerId: customers[0].id,
      issueDate: '2025-01-15',
      lines: [{ sku: products[0].sku, qty: 2 }],
    });

    const result = addLine(invoiceResult.value, { sku: products[1].sku, qty: 3 });

    assert.equal(result.ok, true);
    assert.equal(result.value.lines[1].discountPercent, 0);
  });

  it('returns DISCOUNT_INVALID when addLine has invalid discountPercent', () => {
    const products = listProducts();
    const customers = listCustomers();
    const invoiceResult = createInvoice({
      customerId: customers[0].id,
      issueDate: '2025-01-15',
      lines: [{ sku: products[0].sku, qty: 2 }],
    });

    const result = addLine(invoiceResult.value, { sku: products[1].sku, qty: 3, discountPercent: 150 });

    assert.equal(result.ok, false);
    assert.equal(result.error, 'DISCOUNT_INVALID');
  });

  it('preserves other properties when adding a line', () => {
    const products = listProducts();
    const customers = listCustomers();
    const customer = customers[0];
    const invoiceResult = createInvoice({
      customerId: customer.id,
      issueDate: '2025-01-15',
      lines: [{ sku: products[0].sku, qty: 2 }],
    });

    const result = addLine(invoiceResult.value, { sku: products[1].sku, qty: 1 });

    assert.equal(result.value.customerId, customer.id);
    assert.equal(result.value.issueDate, '2025-01-15');
    assert.equal(result.value.status, 'draft');
  });

  it('can add multiple different products', () => {
    const products = listProducts();
    const customers = listCustomers();
    let invoice = createInvoice({
      customerId: customers[0].id,
      issueDate: '2025-01-15',
      lines: [{ sku: products[0].sku, qty: 1 }],
    }).value;

    invoice = addLine(invoice, { sku: products[1].sku, qty: 1 }).value;
    invoice = addLine(invoice, { sku: products[2].sku, qty: 1 }).value;

    assert.equal(invoice.lines.length, 3);
    assert.equal(invoice.lines[0].sku, products[0].sku);
    assert.equal(invoice.lines[1].sku, products[1].sku);
    assert.equal(invoice.lines[2].sku, products[2].sku);
  });

  it('can add to a line multiple times', () => {
    const products = listProducts();
    const customers = listCustomers();
    let invoice = createInvoice({
      customerId: customers[0].id,
      issueDate: '2025-01-15',
      lines: [{ sku: products[0].sku, qty: 1 }],
    }).value;

    invoice = addLine(invoice, { sku: products[0].sku, qty: 2 }).value;
    invoice = addLine(invoice, { sku: products[0].sku, qty: 3 }).value;

    assert.equal(invoice.lines.length, 1);
    assert.equal(invoice.lines[0].qty, 6);
  });
});

describe('removeLine', () => {
  it('removes a line from a draft invoice', () => {
    const products = listProducts();
    const customers = listCustomers();
    const invoiceResult = createInvoice({
      customerId: customers[0].id,
      issueDate: '2025-01-15',
      lines: [
        { sku: products[0].sku, qty: 2 },
        { sku: products[1].sku, qty: 3 },
      ],
    });

    const result = removeLine(invoiceResult.value, products[1].sku);

    assert.equal(result.ok, true);
    assert.equal(result.value.lines.length, 1);
    assert.equal(result.value.lines[0].sku, products[0].sku);
  });

  it('does not mutate the original invoice', () => {
    const products = listProducts();
    const customers = listCustomers();
    const invoiceResult = createInvoice({
      customerId: customers[0].id,
      issueDate: '2025-01-15',
      lines: [
        { sku: products[0].sku, qty: 2 },
        { sku: products[1].sku, qty: 3 },
      ],
    });

    const invoice = invoiceResult.value;
    const invoiceCopy = JSON.parse(JSON.stringify(invoice));

    removeLine(invoice, products[1].sku);

    assert.deepEqual(invoice, invoiceCopy);
  });

  it('returns NOT_DRAFT for non-draft invoice', () => {
    const products = listProducts();
    const customers = listCustomers();
    const invoiceResult = createInvoice({
      customerId: customers[0].id,
      issueDate: '2025-01-15',
      lines: [
        { sku: products[0].sku, qty: 2 },
        { sku: products[1].sku, qty: 3 },
      ],
    });

    const invoice = invoiceResult.value;
    invoice.status = 'sent';

    const result = removeLine(invoice, products[1].sku);

    assert.equal(result.ok, false);
    assert.equal(result.error, 'NOT_DRAFT');
  });

  it('returns LINE_NOT_FOUND when SKU is not on invoice', () => {
    const products = listProducts();
    const customers = listCustomers();
    const invoiceResult = createInvoice({
      customerId: customers[0].id,
      issueDate: '2025-01-15',
      lines: [{ sku: products[0].sku, qty: 2 }],
    });

    const result = removeLine(invoiceResult.value, 'UNKNOWN-SKU');

    assert.equal(result.ok, false);
    assert.equal(result.error, 'LINE_NOT_FOUND');
  });

  it('returns NO_LINES when removing the last line', () => {
    const products = listProducts();
    const customers = listCustomers();
    const invoiceResult = createInvoice({
      customerId: customers[0].id,
      issueDate: '2025-01-15',
      lines: [{ sku: products[0].sku, qty: 2 }],
    });

    const result = removeLine(invoiceResult.value, products[0].sku);

    assert.equal(result.ok, false);
    assert.equal(result.error, 'NO_LINES');
  });

  it('preserves other properties when removing a line', () => {
    const products = listProducts();
    const customers = listCustomers();
    const customer = customers[0];
    const invoiceResult = createInvoice({
      customerId: customer.id,
      issueDate: '2025-01-15',
      lines: [
        { sku: products[0].sku, qty: 2 },
        { sku: products[1].sku, qty: 3 },
      ],
    });

    const result = removeLine(invoiceResult.value, products[1].sku);

    assert.equal(result.value.customerId, customer.id);
    assert.equal(result.value.issueDate, '2025-01-15');
    assert.equal(result.value.status, 'draft');
  });

  it('can remove multiple lines one at a time', () => {
    const products = listProducts();
    const customers = listCustomers();
    let invoice = createInvoice({
      customerId: customers[0].id,
      issueDate: '2025-01-15',
      lines: [
        { sku: products[0].sku, qty: 1 },
        { sku: products[1].sku, qty: 1 },
        { sku: products[2].sku, qty: 1 },
      ],
    }).value;

    invoice = removeLine(invoice, products[0].sku).value;
    assert.equal(invoice.lines.length, 2);

    invoice = removeLine(invoice, products[2].sku).value;
    assert.equal(invoice.lines.length, 1);
    assert.equal(invoice.lines[0].sku, products[1].sku);
  });

  it('fails gracefully when trying to remove from an invoice that would have no lines', () => {
    const products = listProducts();
    const customers = listCustomers();
    const invoiceResult = createInvoice({
      customerId: customers[0].id,
      issueDate: '2025-01-15',
      lines: [
        { sku: products[0].sku, qty: 1 },
        { sku: products[1].sku, qty: 1 },
      ],
    });

    let invoice = invoiceResult.value;
    invoice = removeLine(invoice, products[0].sku).value;
    assert.equal(invoice.lines.length, 1);

    // Try to remove the last line - should fail
    const result = removeLine(invoice, products[1].sku);
    assert.equal(result.ok, false);
    assert.equal(result.error, 'NO_LINES');
  });
});

describe('nextInvoiceNumber', () => {
  it('starts at 0001 for a new year with no existing numbers', () => {
    const number = nextInvoiceNumber([], '2025-01-15');
    assert.equal(number, 'INV-2025-0001');
  });

  it('returns 0001 when existing numbers are from previous year', () => {
    const existingNumbers = ['INV-2024-0001', 'INV-2024-0002'];
    const number = nextInvoiceNumber(existingNumbers, '2025-01-15');
    assert.equal(number, 'INV-2025-0001');
  });

  it('increments counter for same year', () => {
    const existingNumbers = ['INV-2025-0001', 'INV-2025-0002'];
    const number = nextInvoiceNumber(existingNumbers, '2025-06-01');
    assert.equal(number, 'INV-2025-0003');
  });

  it('handles unsorted existing numbers', () => {
    const existingNumbers = ['INV-2025-0005', 'INV-2025-0001', 'INV-2025-0003'];
    const number = nextInvoiceNumber(existingNumbers, '2025-12-31');
    assert.equal(number, 'INV-2025-0006');
  });

  it('pads counter to 4 digits', () => {
    const existingNumbers = Array.from({ length: 100 }, (_, i) => `INV-2025-${String(i + 1).padStart(4, '0')}`);
    const number = nextInvoiceNumber(existingNumbers, '2025-06-15');
    assert.equal(number, 'INV-2025-0101');
  });

  it('ignores numbers from other years', () => {
    const existingNumbers = ['INV-2023-9999', 'INV-2024-0050', 'INV-2025-0002', 'INV-2026-0001'];
    const number = nextInvoiceNumber(existingNumbers, '2025-03-15');
    assert.equal(number, 'INV-2025-0003');
  });

  it('handles large counters', () => {
    const existingNumbers = ['INV-2025-9998'];
    const number = nextInvoiceNumber(existingNumbers, '2025-12-31');
    assert.equal(number, 'INV-2025-9999');
  });

  it('extracts year correctly from date', () => {
    const number1 = nextInvoiceNumber([], '2024-01-01');
    assert.equal(number1, 'INV-2024-0001');

    const number2 = nextInvoiceNumber([], '2099-12-31');
    assert.equal(number2, 'INV-2099-0001');
  });

  it('works with any date in the year', () => {
    const existingNumbers = ['INV-2025-0001'];
    const number1 = nextInvoiceNumber(existingNumbers, '2025-01-01');
    const number2 = nextInvoiceNumber(existingNumbers, '2025-06-15');
    const number3 = nextInvoiceNumber(existingNumbers, '2025-12-31');

    assert.equal(number1, 'INV-2025-0002');
    assert.equal(number2, 'INV-2025-0002');
    assert.equal(number3, 'INV-2025-0002');
  });
});

describe('issueInvoice', () => {
  it('issues a draft invoice with a number and changed status', () => {
    const products = listProducts();
    const customers = listCustomers();
    const invoiceResult = createInvoice({
      customerId: customers[0].id,
      issueDate: '2025-01-15',
      lines: [{ sku: products[0].sku, qty: 2 }],
    });

    const result = issueInvoice(invoiceResult.value, []);

    assert.equal(result.ok, true);
    assert.equal(result.value.status, 'issued');
    assert.equal(result.value.number, 'INV-2025-0001');
  });

  it('assigns the next available number', () => {
    const products = listProducts();
    const customers = listCustomers();
    const invoiceResult = createInvoice({
      customerId: customers[0].id,
      issueDate: '2025-02-15',
      lines: [{ sku: products[0].sku, qty: 1 }],
    });

    const existingNumbers = ['INV-2025-0001', 'INV-2025-0002'];
    const result = issueInvoice(invoiceResult.value, existingNumbers);

    assert.equal(result.value.number, 'INV-2025-0003');
  });

  it('uses the invoice\'s issue date for numbering', () => {
    const products = listProducts();
    const customers = listCustomers();
    const invoiceResult = createInvoice({
      customerId: customers[0].id,
      issueDate: '2024-12-31',
      lines: [{ sku: products[0].sku, qty: 1 }],
    });

    const result = issueInvoice(invoiceResult.value, []);

    assert.equal(result.value.number, 'INV-2024-0001');
  });

  it('does not mutate the original invoice', () => {
    const products = listProducts();
    const customers = listCustomers();
    const invoiceResult = createInvoice({
      customerId: customers[0].id,
      issueDate: '2025-01-15',
      lines: [{ sku: products[0].sku, qty: 2 }],
    });

    const invoice = invoiceResult.value;
    const invoiceCopy = JSON.parse(JSON.stringify(invoice));

    issueInvoice(invoice, []);

    assert.deepEqual(invoice, invoiceCopy);
  });

  it('returns NOT_DRAFT for non-draft invoice', () => {
    const products = listProducts();
    const customers = listCustomers();
    const invoiceResult = createInvoice({
      customerId: customers[0].id,
      issueDate: '2025-01-15',
      lines: [{ sku: products[0].sku, qty: 2 }],
    });

    const invoice = invoiceResult.value;
    invoice.status = 'issued';

    const result = issueInvoice(invoice, []);

    assert.equal(result.ok, false);
    assert.equal(result.error, 'NOT_DRAFT');
  });

  it('preserves all other invoice properties', () => {
    const products = listProducts();
    const customers = listCustomers();
    const customer = customers[0];
    const sku = products[0].sku;
    const invoiceResult = createInvoice({
      customerId: customer.id,
      issueDate: '2025-03-15',
      lines: [{ sku, qty: 5 }],
    });

    const result = issueInvoice(invoiceResult.value, []);

    assert.equal(result.value.customerId, customer.id);
    assert.equal(result.value.issueDate, '2025-03-15');
    assert.equal(result.value.lines.length, 1);
    assert.equal(result.value.lines[0].sku, sku);
    assert.equal(result.value.lines[0].qty, 5);
  });

  it('can issue multiple invoices from the same year', () => {
    const products = listProducts();
    const customers = listCustomers();
    const existingNumbers = [];

    for (let i = 0; i < 3; i++) {
      const invoiceResult = createInvoice({
        customerId: customers[0].id,
        issueDate: '2025-01-15',
        lines: [{ sku: products[i % products.length].sku, qty: 1 }],
      });

      const result = issueInvoice(invoiceResult.value, existingNumbers);
      assert.equal(result.ok, true);
      existingNumbers.push(result.value.number);
    }

    assert.deepEqual(existingNumbers, ['INV-2025-0001', 'INV-2025-0002', 'INV-2025-0003']);
  });

  it('resets counter for new year', () => {
    const products = listProducts();
    const customers = listCustomers();
    const existingNumbers = ['INV-2024-0050'];

    const invoice2024 = createInvoice({
      customerId: customers[0].id,
      issueDate: '2024-12-31',
      lines: [{ sku: products[0].sku, qty: 1 }],
    }).value;

    const invoice2025 = createInvoice({
      customerId: customers[0].id,
      issueDate: '2025-01-01',
      lines: [{ sku: products[0].sku, qty: 1 }],
    }).value;

    const result2024 = issueInvoice(invoice2024, existingNumbers);
    existingNumbers.push(result2024.value.number);

    const result2025 = issueInvoice(invoice2025, existingNumbers);

    assert.equal(result2024.value.number, 'INV-2024-0051');
    assert.equal(result2025.value.number, 'INV-2025-0001');
  });
});

